<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {ArrowUpRight,CalendarDays,UserRoundCog,History} from 'lucide-vue-next'
import CallAction from './CallAction.vue'
import IsolationStatistics from './IsolationStatistics.vue'
import IsolationProspectActivity from './IsolationProspectActivity.vue'
import IsolationVisits from './IsolationVisits.vue'
import SidePanel from './SidePanel.vue'
import IsolationBulkAssignment from './IsolationBulkAssignment.vue'
import IsolationDistribution from './IsolationDistribution.vue'
const showStatistics=ref(false)
const lineLabels:Record<string,string>={active:'Active',inactive:'Inactive',unknown:'Indéterminée',indeterminate:'Indéterminée',unreachable:'Non joignable',reachable:'Potentiellement joignable'}
function lineTone(value:string){return ['active','reachable'].includes(value)?'positive':['inactive','unreachable'].includes(value)?'negative':'neutral'}
const props=defineProps<{role:string;portal:(path:string,body?:any)=>Promise<any>;request:(path:string,body?:any,method?:string)=>Promise<any>}>()
const visitsPanel=ref<any>(null),visitBusy=ref(false)
const visitsOpen=ref(false),visitProspect=ref<number|undefined>(undefined)
const activity=ref<any>(null),commercialStatus=ref(''),dueOnly=ref(false),callbacksDue=ref(0)
const rows=ref<any[]>([]),count=ref(0),page=ref(1),search=ref(''),owner=ref(''),busy=ref(false),error=ref(''),selected=ref<any>(null),reason=ref('')
const people=ref<any[]>([]),peoplePage=ref(1),peopleCount=ref(0),peopleSearch=ref(''),target=ref(''),history=ref<any>(null),historyPage=ref(1),historyCount=ref(0),historyRows=ref<any[]>([])
async function run(action:()=>Promise<void>){busy.value=true;error.value='';try{await action()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function load(){const data=await props.request(`work-queue/?page=${page.value}&search=${encodeURIComponent(search.value)}&owner=${encodeURIComponent(owner.value)}&commercial_status=${encodeURIComponent(commercialStatus.value)}&due=${dueOnly.value}`);rows.value=data.results;count.value=data.count;callbacksDue.value=(await props.request('workspace-dashboard/')).callbacks_due}
async function directory(step=0){peoplePage.value=step?peoplePage.value+step:1;target.value='';const data=await props.portal(`isolation/setters/?page=${peoplePage.value}&search=${encodeURIComponent(peopleSearch.value)}`);people.value=data.results;peopleCount.value=data.count}
async function open(row:any){await run(async()=>{selected.value=await props.request(`work-queue/${row.id}/`);reason.value='';await directory()})}
async function assign(release=false){await run(async()=>{const row=selected.value;const body:any={revision:row.revision,reason:reason.value};if(!release)body.proof=(await props.portal('isolation/setters/',{prospect_id:row.id,setter_id:Number(target.value)})).proof;await props.request(`work-queue/${row.id}/${release?'unassign':'assign'}/`,body);selected.value=null;await load()})}
async function callIntent(row:any,id:string){
 const current=await props.request(`work-queue/${row.id}/`)
 return props.request(`work-queue/${row.id}/call-intent/`,{revision:current.revision,request_id:id})
}
async function loadHistory(){const data=await props.request(`work-queue/${history.value.id}/history/?page=${historyPage.value}`);historyRows.value=data.results;historyCount.value=data.count}
onMounted(()=>run(load))
</script>
<template><section class="crm-isolation-list"><button class="secondary" @click="showStatistics=!showStatistics">{{showStatistics?'Masquer les statistiques':'Voir les statistiques'}}</button><IsolationStatistics v-if="showStatistics" :role="role" :request="request"/><h3>{{role==='administrator'?'Affectations des prospects Isolation':'Mes prospects Isolation'}}</h3><p v-if="error" role="alert">{{error}}</p><p>La validité de format et l’état technique de la ligne ne prouvent pas qu’une personne décroche. Un appel nécessite une confirmation explicite ; aucune vérification Lookup n’est lancée automatiquement.</p><button class="secondary" :disabled="busy" @click="visitProspect=undefined;visitsOpen=true">Toutes les visites de mon périmètre</button><p v-if="callbacksDue" role="status">{{callbacksDue}} rappel(s) arrivé(s) à échéance dans votre périmètre.</p><form @submit.prevent="run(async()=>{page=1;await load()})"><label>Nom, téléphone ou référence<input v-model="search"></label><label v-if="role==='administrator'">Responsable<input v-model="owner" placeholder="Vide : tous ; unassigned : sans affectation ; ou identifiant setter"></label><label>Résultat commercial<select v-model="commercialStatus"><option value="">Tous</option><option value="to_contact">À contacter</option><option value="in_progress">En cours</option><option value="callback">À rappeler</option><option value="interested">Intéressé</option><option value="not_interested">Non intéressé</option><option value="unreachable">Non joint</option></select></label><label><input v-model="dueOnly" type="checkbox">Rappels à échéance uniquement</label><button class="secondary" :disabled="busy">Rechercher / actualiser</button></form><IsolationDistribution v-if="role==='administrator'" :rows="rows" :portal="portal" :request="request" @changed="run(load)"/><IsolationBulkAssignment v-if="role==='administrator'" :rows="rows" :portal="portal" :request="request" @changed="run(load)"/><div class="table-scroll isolation-table"><table><thead><tr><th>Contact</th><th>État de la ligne</th><th>Qualification</th><th>Setter</th><th>Prochaine action</th><th>Actions</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><button class="contact-name" @click="activity=row"><span class="contact-initial">{{(row.name||'?').slice(0,1).toUpperCase()}}</span><span><strong>{{row.name||'Prospect sans nom'}}</strong><small>{{row.phone||row.raw_phone}}</small></span></button><small>{{row.reference||row.campaign.name}}</small></td><td><span class="crm-badge" :class="lineTone(row.line_status)">{{lineLabels[row.line_status]||row.line_status}}</span><small>Format : {{row.validity==='valid'?'valide':row.validity==='invalid'?'invalide':'à vérifier'}}</small></td><td><span class="crm-badge" :class="row.commercial_status==='interested'?'positive':row.commercial_status==='callback'?'warning':'neutral'">{{row.commercial_label}}</span></td><td>{{row.assigned_setter?.name||'Non affecté'}}</td><td><span v-if="row.callback_at" :class="{'crm-overdue':row.callback_due}">{{new Date(row.callback_at).toLocaleString('fr-FR')}}</span><span v-else class="subtle">Aucun rappel</span></td><td><div class="row-actions"><button class="secondary" :disabled="busy" @click="activity=row"><ArrowUpRight :size="14"/>Fiche</button><button class="secondary" :disabled="busy" title="Visites et réservation" aria-label="Visites et réservation" @click="visitProspect=row.id;visitsOpen=true"><CalendarDays :size="15"/></button><template v-if="role==='administrator'"><button class="secondary" :disabled="busy" title="Affecter ou réattribuer" aria-label="Affecter ou réattribuer" @click="open(row)"><UserRoundCog :size="15"/></button><button class="secondary" :disabled="busy" title="Historique d’affectation" aria-label="Historique d’affectation" @click="run(async()=>{history=row;historyPage=1;await loadHistory()})"><History :size="15"/></button></template></div><CallAction v-if="role==='setter'" workspace="isolation" :resource-id="row.id" :phone="row.phone||row.raw_phone" :portal="portal" :prepare="(id:string)=>callIntent(row,id)" :disabled="busy"/></td></tr><tr v-if="!rows.length"><td colspan="6" class="empty-state">{{busy?'Chargement des prospects…':'Aucun prospect dans votre périmètre.'}}</td></tr></tbody></table></div><p>{{count}} prospect(s) · page {{page}}</p><button class="secondary" :disabled="busy||page===1" @click="run(async()=>{page--;await load()})">Précédent</button><button class="secondary" :disabled="busy||page*25>=count" @click="run(async()=>{page++;await load()})">Suivant</button><SidePanel :open="visitsOpen" title="Visites et formulaire C2" eyebrow="ISOLATION" :close-disabled="visitBusy" @request-close="visitsPanel?.close()"><IsolationVisits v-if="visitsOpen" ref="visitsPanel" :key="visitProspect||0" :prospect-id="visitProspect" :role="role" :portal="portal" :request="request" @busy="visitBusy=$event" @close="visitsOpen=false" @changed="run(load)"/></SidePanel><IsolationProspectActivity v-if="activity" :key="activity.id" :prospect-id="activity.id" :request="request" @close="activity=null" @saved="run(load)"/><section v-if="selected&&role==='administrator'"><h4>Affectation : {{selected.name||selected.raw_phone}}</h4><form @submit.prevent="run(()=>directory())"><label>Rechercher un setter Isolation actif<input v-model="peopleSearch"></label><button class="secondary" :disabled="busy">Rechercher</button></form><form @submit.prevent="assign()"><label>Nouveau responsable<select v-model="target" required><option value="">Choisir un setter</option><option v-for="person in people" :key="person.id" :value="String(person.id)" :disabled="person.id===selected.assigned_setter?.id">{{person.name}}</option></select></label><p>{{peopleCount}} setter(s) · page {{peoplePage}}</p><button type="button" class="secondary" :disabled="busy||peoplePage===1" @click="run(()=>directory(-1))">Précédent</button><button type="button" class="secondary" :disabled="busy||peoplePage*25>=peopleCount" @click="run(()=>directory(1))">Suivant</button><label>Motif obligatoire<textarea v-model="reason" required maxlength="1000"></textarea></label><button class="primary" :disabled="busy||!target">Confirmer l’affectation</button><button type="button" class="secondary" :disabled="busy||!selected.assigned_setter||!reason.trim()" @click="assign(true)">Retirer l’affectation</button><button type="button" class="secondary" :disabled="busy" @click="selected=null">Fermer</button></form></section><section v-if="history"><h4>Historique d’affectation</h4><article v-for="entry in historyRows" :key="entry.id"><small>{{new Date(entry.created_at).toLocaleString('fr-FR')}}</small><pre>{{JSON.stringify(entry.metadata,null,2)}}</pre></article><button class="secondary" :disabled="busy||historyPage===1" @click="run(async()=>{historyPage--;await loadHistory()})">Précédent</button><button class="secondary" :disabled="busy||historyPage*25>=historyCount" @click="run(async()=>{historyPage++;await loadHistory()})">Suivant</button><button class="secondary" @click="history=null">Fermer l’historique</button></section></section></template>

<style scoped>
.isolation-table{margin:22px 0;border:1px solid #e2e8f0;border-radius:8px}.isolation-table table{min-width:950px}.contact-name{display:flex;align-items:center;gap:10px;border:0;background:none;text-align:left;cursor:pointer;color:#263b55;padding:0}.contact-name strong{font-size:13px;font-weight:600}.contact-initial{display:grid;place-items:center;flex-shrink:0;width:34px;height:34px;border-radius:50%;background:#eaf1fc;color:#497bb5;font-size:13px;font-weight:600}.contact-name small{margin-top:4px!important}.row-actions{display:flex;align-items:center;gap:6px;white-space:nowrap}.row-actions button{display:inline-flex;align-items:center;gap:5px;padding:7px 9px}.contact-name:hover strong{color:#2563a6}.crm-overdue{color:#b35b3b}.empty-state{text-align:center;padding:42px!important;color:#64748b}
.crm-isolation-list>h3{font-size:20px;margin:0 0 5px}.crm-isolation-list>h3+p{color:#6b7c93;margin:0 0 18px;max-width:760px;font-size:13px}.crm-isolation-list>form:first-of-type{display:grid;grid-template-columns:minmax(230px,1.4fr) minmax(180px,1fr) minmax(160px,.8fr) auto auto;gap:10px;align-items:end;padding:14px;margin:18px 0 0;background:#f7f9fc;border:1px solid #dce5ef;border-radius:8px}.crm-isolation-list>form:first-of-type label{display:grid;gap:5px;font-size:11px;font-weight:650;color:#64748b}.crm-isolation-list>form:first-of-type input,.crm-isolation-list>form:first-of-type select{min-height:36px;box-sizing:border-box;border:1px solid #d6e0eb;border-radius:5px;background:#fff;padding:7px 9px;color:#263b55}.crm-isolation-list>form:first-of-type label:last-of-type{display:flex;align-items:center;gap:7px;min-height:36px;white-space:nowrap}.crm-isolation-list>form:first-of-type label:last-of-type input{min-height:0}.crm-isolation-list>form:first-of-type button{min-height:36px;white-space:nowrap}.isolation-table{border-radius:7px;margin-top:14px;box-shadow:0 1px 2px #23324708}.isolation-table thead th{background:#f5f8fc!important;color:#65788f!important;font-size:11px!important;letter-spacing:.02em}.isolation-table tbody tr:hover{background:#f9fbfe}.contact-initial{border-radius:50%;background:#e3effc;color:#2376bb}.row-actions .secondary{border-color:#d8e3ef;background:#fff}.crm-isolation-list>p[role="status"]{margin:12px 0;padding:9px 12px;background:#fff7e7;border:1px solid #f2dfae;border-radius:6px;color:#805b17;font-size:12px}@media(max-width:1100px){.crm-isolation-list>form:first-of-type{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:620px){.crm-isolation-list>form:first-of-type{grid-template-columns:1fr}.crm-isolation-list>form:first-of-type button{width:100%}}
</style>
